just bisected this. introduced in v3.0.0 (beta.10 works fine) with this PR: https://github.com/node-fetch/node-fetch/pull/1064

_added heap memory usage:_
```js
import { Agent } from "node:http";
import { memoryUsage } from "node:process";
import fetch from "node-fetch";

const agent = new Agent({ keepAlive: true });

for (let i = 0; ; i++) {
  const { status } = await fetch("http://example.com", { agent });

  if (i % 100 === 0) console.log(i, memoryUsage().heapUsed, status);
}
```

